import{_ as o,c as a,o as t,a2 as i}from"./chunks/framework.QTfwLiL8.js";const g=JSON.parse('{"title":"0035 Observability2.0 Victorialogs","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0035-observability2.0-victorialogs","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0035-observability2.0-victorialogs/README.md","to":"README.md"},"title":"0035 Observability2.0 Victorialogs","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0035-observability2.0-victorialogs/_index.md","filePath":"docs/proposals/0035-observability2.0-victorialogs/_index.md","lastUpdated":null}'),r={name:"docs/proposals/0035-observability2.0-victorialogs/_index.md"};function n(s,e,l,c,d,h){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="gep-0035-migrating-from-vali-to-victorialogs" tabindex="-1">GEP-0035: Migrating from Vali to VictoriaLogs <a class="header-anchor" href="#gep-0035-migrating-from-vali-to-victorialogs" aria-label="Permalink to &quot;GEP-0035: Migrating from Vali to VictoriaLogs&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#terminology">Terminology</a></li><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#goals">Goals</a></li><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#non-goals">Non-Goals</a></li></ul></li><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#proposal">Proposal</a></li><li><a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#alternatives">Alternatives</a></li></ul><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><p>Since this document relies on work that has already been done in <a href="https://github.com/gardener/enhancements/blob/main/geps/0035-observability2.0-victorialogs/34-observability2.0-opentelemtry-operator-and-collectors.md" target="_blank" rel="noreferrer">GEP-34</a>, the same terminology applies here as well:</p><ul><li><a href="https://opentelemetry.io/docs/specs/otlp/" target="_blank" rel="noreferrer">OTLP</a>: OpenTelemetry Protocol</li><li><a href="https://opentelemetry.io/docs/collector/" target="_blank" rel="noreferrer">OpenTelemetry Collector</a>: A component that can receive, process, and export telemetry data (logs, metrics, traces).</li><li><a href="https://github.com/credativ/vali" target="_blank" rel="noreferrer">Vali</a>: A fork of Loki 2.2.1 that is used as the log database in the current Gardener observability stack.</li><li><a href="https://github.com/grafana/loki" target="_blank" rel="noreferrer">Loki</a>: A log database that is part of the Grafana ecosystem.</li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>This proposal introduces the deployment of <a href="https://github.com/VictoriaMetrics/VictoriaLogs" target="_blank" rel="noreferrer">VictoriaLogs</a> which will act as the replacement for <a href="https://github.com/credativ/vali" target="_blank" rel="noreferrer">Vali</a> in the control plane of all <code>Shoot</code> clusters that have the logging stack enabled, as well as in <code>Seed</code> clusters and <code>Garden</code> clusters. After the work that has been done on <a href="https://github.com/gardener/gardener/pull/11861" target="_blank" rel="noreferrer">GEP-34</a>, we are in a favourable position to easily switch our storage layer for the clusters&#39; log signals.</p><p>This document fully relies on <a href="https://github.com/gardener/enhancements/blob/main/geps/0035-observability2.0-victorialogs/34-observability2.0-opentelemtry-operator-and-collectors.md" target="_blank" rel="noreferrer">GEP-34</a> having already been implemented. For this reason, it&#39;s expected that the reader is familiar with the concepts and terminology introduced in that GEP.</p><p>A new operator is introduced that will be deployed to the <code>garden</code> namespace of <code>Seed</code> and <code>Garden</code> clusters. This operator will manage the k8s deployment of the new <code>VictoriaLogs</code> instances to the <code>garden</code> namespace of <code>Seed</code> and <code>Garden</code> clusters, as well as to the control plane namespace of <code>Shoot</code> clusters via the <a href="https://github.com/VictoriaMetrics/operator/blob/471ecf6e0ad8839e2e88a6668d962e52e8fd677a/docs/resources/vlsingle.md" target="_blank" rel="noreferrer"><code>VLSingle</code> CustomResource</a>.</p><p>Since we&#39;d like to make the transition from <code>Vali</code> to <code>VictoriaLogs</code> as painless as possible, this proposal also discusses migration in already running landscapes without losing data that has accumulated with the existing <code>Vali</code> instances and gives an implementation plan for that.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Since version v2.3.0, <a href="https://github.com/grafana/loki" target="_blank" rel="noreferrer">Loki</a> has switched from the Apache-2.0 license to a significantly more restrictive AGPLv3 license. Since then, the Observability stack of Gardener has been using <a href="https://github.com/credativ/vali" target="_blank" rel="noreferrer">Vali</a> - a fork of Loki 2.2.1, which is the last official version that maintains the Apache-2.0 license.</p><p>However, the fork maintains only security updates, thus leading to no new features or improvements getting integrated. As such, an upgrade is due so that we can benefit from new technologies and optimizations in the world of log databases.</p><p>One such advancement is <a href="https://opentelemetry.io/docs/specs/otel/protocol/" target="_blank" rel="noreferrer">OTLP</a>, discussed in more detail in <a href="https://github.com/gardener/enhancements/blob/main/geps/0035-observability2.0-victorialogs/34-observability2.0-opentelemtry-operator-and-collectors.md" target="_blank" rel="noreferrer">GEP-34</a>. After careful consideration, we&#39;ve converged to using <a href="https://github.com/VictoriaMetrics/VictoriaLogs" target="_blank" rel="noreferrer">VictoriaLogs</a> as the backend for storing logs. See the <a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#alternatives">Alternatives</a> section for more details on why this choice was made.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Deploy a <code>VictoriaOperator</code> instance in the <code>garden</code> namespace of the <code>Garden</code> cluster.</li><li>Deploy a <code>VictoriaLogs</code> instance in the <code>garden</code> namespace of the <code>Garden</code> cluster via the <code>VLSingle</code> CustomResource.</li><li>Deploy a <code>VictoriaOperator</code> instance to the <code>garden</code> namespace of the <code>Seed</code> clusters.</li><li>Deploy a <code>VictoriaLogs</code> instance in the control plane namespaces of new and existing <code>Shoot</code> clusters via the <code>VLSingle</code> CustomResource.</li><li>Give an appropriate migration strategy from <code>Vali</code> to <code>VictoriaLogs</code> for existing clusters.</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><ul><li>Provide general-purpose tools for migration from <code>Vali</code> to <code>VictoriaLogs</code></li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="_1-deployment-of-victorialogs-on-the-garden-cluster" tabindex="-1">1. Deployment of <code>VictoriaLogs</code> on the <code>Garden</code> Cluster <a class="header-anchor" href="#_1-deployment-of-victorialogs-on-the-garden-cluster" aria-label="Permalink to &quot;1. Deployment of `VictoriaLogs` on the `Garden` Cluster&quot;">​</a></h3><p>This includes 2 steps:</p><ul><li>Deployment of a new <a href="https://github.com/VictoriaMetrics/operator" target="_blank" rel="noreferrer">VictoriaOperator</a> component during the <code>Garden</code> reconciliation flow in the <code>garden</code> namespace.</li><li>Deployment of a <code>VLSingle</code> CustomResource during the <code>Garden</code> reconciliation flow <em>after</em> the <code>VictoriaOperator</code> k8s deployment has finished.</li></ul><p>The <code>VLSingle</code> CustomResource will be managed by the operator and will create a <code>VictoriaLogs</code> k8s deployment in the <code>garden</code> namespace.</p><p>Both new components will implement the already existing pattern that components implement (e.g. OpenTelemetry Operator, Prometheus Operator). That being an implementation of the <code>Deployer</code> interface as well as an additional step in the <code>Garden</code> reconciliation flow.</p><h4 id="sending-logs-to-victorialogs-in-the-garden-cluster" tabindex="-1">Sending Logs to <code>VictoriaLogs</code> in the <code>Garden</code> Cluster <a class="header-anchor" href="#sending-logs-to-victorialogs-in-the-garden-cluster" aria-label="Permalink to &quot;Sending Logs to `VictoriaLogs` in the `Garden` Cluster&quot;">​</a></h4><p>Currently, <code>Vali</code> access is behind a service in the <code>garden</code> namespace. This pattern will remain and log shippers will only be expected to use the <code>OTLP</code> protocol, instead of the <code>Loki</code> protocol, via HTTP when inserting logs to <code>VictoriaLogs</code>. In the <code>Garden</code> cluster, the only log shippers are the <code>FluentBit</code> instances. They will be configured to send logs via <code>OTLP</code>.</p><p>In other words, the <code>VictoriaLogs</code> instance will be exposed via a service in the <code>garden</code> namespace.</p><h3 id="_2-deployment-of-victorialogs-on-seed-clusters" tabindex="-1">2. Deployment of <code>VictoriaLogs</code> on <code>Seed</code> Clusters <a class="header-anchor" href="#_2-deployment-of-victorialogs-on-seed-clusters" aria-label="Permalink to &quot;2. Deployment of `VictoriaLogs` on `Seed` Clusters&quot;">​</a></h3><p>Analogously to the deployment in the <code>Garden</code> cluster, this includes 2 steps:</p><ul><li>Deployment of a new <a href="https://github.com/VictoriaMetrics/operator" target="_blank" rel="noreferrer">VictoriaOperator</a> component during the <code>Seed</code> reconciliation flow in the <code>garden</code> namespace.</li><li>Creation of a <code>VLSingle</code> CustomResource in the <code>garden</code> namespace during the <code>Seed</code> reconciliation flow <em>after</em> the <code>VictoriaOperator</code> k8s deployment has finished.</li></ul><p>The <code>VLSingle</code> CustomResource will be managed by the operator and will create a <code>VictoriaLogs</code> k8s deployment in the <code>garden</code> namespace.</p><h4 id="sending-logs-to-victorialogs-in-the-seed-cluster" tabindex="-1">Sending Logs to <code>VictoriaLogs</code> in the <code>Seed</code> Cluster <a class="header-anchor" href="#sending-logs-to-victorialogs-in-the-seed-cluster" aria-label="Permalink to &quot;Sending Logs to `VictoriaLogs` in the `Seed` Cluster&quot;">​</a></h4><p>Since the setup is the same as in the <code>Garden</code> cluster, see details in <a href="/docs/proposals/0035-observability2.0-victorialogs/readme/#sending-logs-to-victorialogs-in-the-garden-cluster">Sending Logs to VictoriaLogs in the <code>Garden</code> cluster</a>.</p><h3 id="_3-deployment-of-victorialogs-in-the-shoot-control-plane" tabindex="-1">3. Deployment of <code>VictoriaLogs</code> in the <code>Shoot</code> Control Plane <a class="header-anchor" href="#_3-deployment-of-victorialogs-in-the-shoot-control-plane" aria-label="Permalink to &quot;3. Deployment of `VictoriaLogs` in the `Shoot` Control Plane&quot;">​</a></h3><p>During the <code>Shoot</code> reconciliation flow, a <code>VLSingle</code> CustomResource will be created in the control plane namespace of the <code>Shoot</code> cluster. The <code>VictoriaOperator</code> operator deployed in the <code>Seed</code> cluster will manage the <code>VLSingle</code> CustomResource and create a <code>VictoriaLogs</code> k8s deployment.</p><p>Example <code>VLSingle</code> CR:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apiVersion: operator.victoriametrics.com/v1</span></span>\n<span class="line"><span>kind: VLSingle</span></span>\n<span class="line"><span>metadata:</span></span>\n<span class="line"><span>  name: example</span></span>\n<span class="line"><span>  namespace: shoot--local--local</span></span>\n<span class="line"><span>spec:</span></span>\n<span class="line"><span>  storage:</span></span>\n<span class="line"><span>    resources:</span></span>\n<span class="line"><span>      requests:</span></span>\n<span class="line"><span>        storage: 30Gi</span></span>\n<span class="line"><span>  resources:</span></span>\n<span class="line"><span>    requests:</span></span>\n<span class="line"><span>      memory: 100Mi</span></span>\n<span class="line"><span>      cpu: 10m</span></span>\n<span class="line"><span>    limits:</span></span>\n<span class="line"><span>      memory: 300Mi</span></span>\n<span class="line"><span>      cpu: 50m</span></span></code></pre></div><h4 id="sending-logs-to-victorialogs-in-the-shoot-control-plane" tabindex="-1">Sending Logs to <code>VictoriaLogs</code> in the <code>Shoot</code> Control Plane <a class="header-anchor" href="#sending-logs-to-victorialogs-in-the-shoot-control-plane" aria-label="Permalink to &quot;Sending Logs to `VictoriaLogs` in the `Shoot` Control Plane&quot;">​</a></h4><p>Currently, <code>Vali</code> access is behind a service in the namespace of the <code>Shoot</code> control plane. For external access, there exists an ingress in front of the <code>OpenTelemetry Collector</code> in the control plane of <code>Shoot</code> clusters that is used to post logs to <code>Vali</code>. See <a href="https://github.com/gardener/enhancements/blob/main/geps/0035-observability2.0-victorialogs/34-observability2.0-opentelemtry-operator-and-collectors.md" target="_blank" rel="noreferrer">GEP-34</a> for more details.</p><p>The same setup will continue with <code>VictoriaLogs</code>, with the only difference being that the <code>OpenTelemetry Collector</code> will be configured to ship logs to <code>VictoriaLogs</code> via <code>OTLP</code> instead of to <code>Vali</code> via the <code>Loki</code> protocol.</p><h3 id="_4-migration-from-vali-to-victorialogs" tabindex="-1">4. Migration from <code>Vali</code> to <code>VictoriaLogs</code> <a class="header-anchor" href="#_4-migration-from-vali-to-victorialogs" aria-label="Permalink to &quot;4. Migration from `Vali` to `VictoriaLogs`&quot;">​</a></h3><h4 id="data-migration" tabindex="-1">Data Migration <a class="header-anchor" href="#data-migration" aria-label="Permalink to &quot;Data Migration&quot;">​</a></h4><p>During all the replacements of <code>Vali</code> we want to ensure that existing clusters do not get disrupted. For this reason, 2 strategies for migration have been considered:</p><ul><li>&quot;One-shot&quot; migration.</li></ul><p>Reformat all the <code>Vali</code> data into the <code>VictoriaLogs</code> format (or OTLP). There is no tool that exists to do this out of the box.</p><table tabindex="0"><thead><tr><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>Migration step is quick.</td><td>Development of the necessary tooling to do the migration.</td></tr><tr><td>No friction during the migration period since there is only one source of logs after the migration.</td><td>Risk of data loss if something goes wrong during the migration.</td></tr></tbody></table><ul><li>&quot;Dual&quot; migration.</li></ul><p><code>VictoriaLogs</code> get deployed alongside <code>Vali</code> and <em>both</em> backends receive logs.</p><table tabindex="0"><thead><tr><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>No risk of data loss.</td><td>Higher storage cost due to the replication of the logs on both backends.</td></tr><tr><td>No friction during the migration period since all logs are visible in both backends.</td><td></td></tr></tbody></table><p>Due to the &quot;dual&quot; migration not requiring the development of new tooling and having no risk of data loss, it has been chosen as the migration strategy. Both <code>Garden</code> clusters and <code>Seed</code> clusters will rely on this strategy, as well as new and existing <code>Shoot</code> clusters. The deployment alongside <code>Vali</code> will be controlled using two feature gates.</p><h5 id="dual-migration-implementation-details" tabindex="-1">Dual Migration Implementation Details <a class="header-anchor" href="#dual-migration-implementation-details" aria-label="Permalink to &quot;Dual Migration Implementation Details&quot;">​</a></h5><p>To facilitate the &quot;dual&quot; migration, a feature gate <code>DeployVictoriaLogs</code> will be introduced for the <code>gardenlet</code> and the <code>gardener-operator</code> components. When this feature gate is enabled:</p><ul><li>New and existing clusters will have <code>VictoriaLogs</code> deployed <em>alongside</em> <code>Vali</code>.</li><li>The OpenTelemetry Collector will be reconfigured to ship logs to <em>both</em> <code>Vali</code> and <code>VictoriaLogs</code>.</li><li><code>FluentBit</code> instances will be reconfigured to ship logs to <em>both</em> <code>Vali</code> and <code>VictoriaLogs</code>.</li></ul><h5 id="removing-vali-after-the-migration-period" tabindex="-1">Removing <code>Vali</code> after the migration period <a class="header-anchor" href="#removing-vali-after-the-migration-period" aria-label="Permalink to &quot;Removing `Vali` after the migration period&quot;">​</a></h5><p>Removal of <code>Vali</code> will further rely on another feature gate called <code>RemoveVali</code> that will rely on the <code>VictoriaLogs</code> already being enabled for the specific component. This feature gate will be introduced for the <code>gardenlet</code> and the <code>gardener-operator</code> components.</p><p>When this feature gate is enabled, based on whether the retention period has passed since <code>VictoriaLogs</code> has been deployed, <code>Vali</code> will be removed from the cluster. Making the migration into 2 feature gates allows us more safety if any issue occurs, by allowing us to rollback only one of the feature gates. First the <code>DeployVictoriaLogs</code> feature gate can mature, then the <code>RemoveVali</code> feature gate, at which point both can simultaneously be removed.</p><h5 id="resource-utilization-during-the-migration-period" tabindex="-1">Resource utilization during the migration period <a class="header-anchor" href="#resource-utilization-during-the-migration-period" aria-label="Permalink to &quot;Resource utilization during the migration period&quot;">​</a></h5><p>During the migration period, <code>Vali</code> and <code>VictoriaLogs</code> will be running alongside each other. This introduces more resource usage on clusters in the form of:</p><ul><li>CPU Utilization</li><li>Memory Utilization</li><li>Storage Utilization (in the form of k8s PersistentVolumes and PersistentVolumeClaims)</li></ul><p>However, since CPU Utilization and Memory Utilization have been seen to be negligant, the main concern is the Storage Utilization. More precisely, <code>Seed</code> and <code>Garden</code> clusters will see an increase in volume usage by exactly the number of already existing <code>Vali</code> volumes. This concern is primarily for <code>Seed</code> clusters that are hosting a large number of <code>Shoot</code> clusters.</p><p>Thus, it is advised that the <code>DeployVictoriaLogs</code> feature gate is enabled intelligently - starting with less critical clusters, batching the number of <code>Seed</code> clusters that have the feature gate enabled, distributing the feature gate equally among regions so that no single region gets overloaded, etc.</p><h4 id="ui-migration" tabindex="-1">UI Migration <a class="header-anchor" href="#ui-migration" aria-label="Permalink to &quot;UI Migration&quot;">​</a></h4><p>There are 2 main issues that we have with our current observability platform - Plutono:</p><ul><li>Plutono is a fork of Grafana and as such it lags behind the new features in Grafana. Same as <code>Vali</code>, it only receives security updates.</li><li>Plutono does not support <code>VictoriaLogs</code> as a data source</li></ul><p>For this reason, our UI for logs will temporarily be replaced with the built-in web UI that <code>VictoriaLogs</code> ships with. Plutono will remain as the dashboard for visualising metrics and dashboards. <a href="https://github.com/gardener/monitoring/issues/52" target="_blank" rel="noreferrer">There is a plan</a> to migrate to <a href="https://github.com/perses/perses" target="_blank" rel="noreferrer">Perses</a> in the near future, which will unify the interfaces again, but this is out of scope of this GEP.</p><hr><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><h3 id="developing-our-own-operator-for-the-victorialogs-deployments" tabindex="-1">Developing our own operator for the <code>VictoriaLogs</code> deployments <a class="header-anchor" href="#developing-our-own-operator-for-the-victorialogs-deployments" aria-label="Permalink to &quot;Developing our own operator for the `VictoriaLogs` deployments&quot;">​</a></h3><p>Taking into account the work that would require maintaining such an operator and the negligible benefits that would provide, it has been decided that using the already existing community driven operator would be more beneficial in the long run.</p><h3 id="clickhouse-instead-of-victorialogs" tabindex="-1">ClickHouse instead of <code>VictoriaLogs</code> <a class="header-anchor" href="#clickhouse-instead-of-victorialogs" aria-label="Permalink to &quot;ClickHouse instead of `VictoriaLogs`&quot;">​</a></h3><p>When choosing a new log database, <a href="https://github.com/ClickHouse/ClickHouse" target="_blank" rel="noreferrer">ClickHouse</a> was the only mainstream alternative that maintains its Apache-2.0 license, is performant and widely used. However after researching it as an option, it was found that ClickHouse:</p><ul><li>Is more complicated for operating</li><li>Has an SQL-like query language for querying logs.</li></ul><p>In contrast, <code>VictoriaLogs</code>:</p><ul><li>Is simple for deployment and operating</li><li>Has a query language that is more similar to the LogQL that <code>Vali</code> uses making the transition easier.</li></ul><p>Furthermore, <code>VictoriaLogs</code> stood out with other great qualities, such as:</p><ul><li>Vibrant community support</li><li>Responsiveness of the code owners</li><li>Performance</li></ul>',77)]))}const u=o(r,[["render",n]]);export{g as __pageData,u as default};
